# The MCP endpoint (generated by maquina:mcp): JSON-RPC over one POST /mcp,
# protocol revision 2026-07-28 only. Stateless: every request carries its
# protocol version in params._meta and mirrors it, the method and (for
# tools/call) the tool name in headers. There is no initialize, no
# Mcp-Session-Id and no SSE; GET and DELETE answer 405.
#
# A bearer token is not a cookie session, so Current.user stays nil here.
# Tools get the token's user through an Mcp::UserScope instead.
class McpController < ActionController::API
  include McpAuthenticatable

  SUPPORTED_VERSIONS = [Mcp::PROTOCOL_VERSION].freeze
  PROTOCOL_VERSION_META = "io.modelcontextprotocol/protocolVersion"
  CLIENT_CAPABILITIES_META = "io.modelcontextprotocol/clientCapabilities"
  SERVER_INFO_META = "io.modelcontextprotocol/serverInfo"
  BASE64_SENTINEL = /\A=\?base64\?(.*)\?=\z/
  DISCOVER_TTL_MS = 3_600_000
  TOOLS_TTL_MS = 300_000

  # Every error this endpoint returns, with its JSON-RPC code and HTTP
  # status. The codes are not interchangeable: an unknown tool or resource is
  # -32602 (never -32002), an unknown method is -32601 with a 404, and a tool
  # that fails is not an error at all but a result with isError: true.
  # -32021 is defined for completeness; no v1 path needs a client capability.
  # -32001 and -32000 are this server's auth and rate-limit codes.
  ERRORS = {
    parse_error: {code: -32_700, status: :bad_request, message: "Parse error: the body is not JSON"},
    invalid_request: {code: -32_600, status: :bad_request, message: "Invalid request"},
    method_not_found: {code: -32_601, status: :not_found, message: "Method not found"},
    missing_meta: {code: -32_602, status: :bad_request, message: "Invalid params"},
    invalid_params: {code: -32_602, status: :ok, message: "Invalid params"},
    internal_error: {code: -32_603, status: :ok, message: "Internal error"},
    header_mismatch: {code: -32_020, status: :bad_request, message: "Header mismatch"},
    missing_required_client_capability: {code: -32_021, status: :bad_request, message: "Missing required client capability"},
    unsupported_protocol_version: {code: -32_022, status: :bad_request, message: "Unsupported protocol version"},
    unauthorized: {code: -32_001, status: :unauthorized, message: "Invalid or expired token"},
    insufficient_scope: {code: -32_001, status: :forbidden, message: "This tool changes data and needs the write scope"},
    rate_limited: {code: -32_000, status: :too_many_requests, message: "Too many requests; wait a minute and retry"}
  }.freeze

  wrap_parameters false

  # Keyed on the token, not the address: agents share egress IPs and one turn
  # sends several calls.
  rate_limit to: 120, within: 1.minute, only: :create, by: -> { mcp_rate_limit_key },
    with: -> { render_rpc_error(:rate_limited, headers: {"Retry-After" => "60"}) }

  def create
    body = parse_body
    return render_rpc_error(:parse_error) if body == :unparseable
    return render_rpc_error(:invalid_request, "Send one JSON-RPC request object; batches are not supported") unless body.is_a?(Hash)
    return head :accepted unless body.key?("id")

    @rpc_id = body["id"]
    return render_rpc_error(:invalid_request, "id must be a string or an integer") unless @rpc_id.is_a?(String) || @rpc_id.is_a?(Integer)
    return render_rpc_error(:invalid_request, %(jsonrpc must be "2.0")) unless body["jsonrpc"] == "2.0"

    method = body["method"]
    return render_rpc_error(:invalid_request, "method must be a string") unless method.is_a?(String)
    return refuse_initialize if method == "initialize"

    params = as_object(body["params"])
    return if refused_meta?(params) || refused_headers?(method, params)

    handle_rpc(method, params)
  end

  # GET and DELETE belonged to the SSE stream and the session, which this
  # revision removed. Answered on purpose: a routing 404 reads as a wrong URL.
  def method_not_allowed
    response.set_header("Allow", "POST")
    head :method_not_allowed
  end

  private

  def handle_rpc(method, params)
    case method
    when "server/discover" then render_result(discover)
    when "tools/list" then with_token { render_result(list_tools) }
    when "tools/call" then with_token { call_tool(params) }
    else render_rpc_error(:method_not_found, "Method not found: #{method}")
    end
  end

  def discover
    {supportedVersions: SUPPORTED_VERSIONS, capabilities: {tools: {}}, ttlMs: DISCOVER_TTL_MS, cacheScope: "public"}
  end

  # Private: the list depends on the token's user, so a shared cache must
  # never hand it to another caller.
  def list_tools
    {tools: Mcp::ToolDefinitions.for(@mcp_user), ttlMs: TOOLS_TTL_MS, cacheScope: "private"}
  end

  def call_tool(params)
    name = params["name"]
    owner = Mcp::ToolDefinitions.owner(name, @mcp_user) if name.is_a?(String)
    return render_rpc_error(:invalid_params, "Unknown tool: #{name}") unless owner
    return refuse_insufficient_scope if owner::WRITE_TOOLS.include?(name) && !@access_token.scopes.include?("write")

    Rails.logger.info("[MCP] tools/call #{name} user_id=#{@mcp_user.id}")
    scope = Mcp::UserScope.new(@mcp_user, oauth_scopes: @access_token.scopes)
    render_result(Mcp::Tools.call(name, params["arguments"], scope: scope))
  rescue Mcp::Tools::InvalidParams => error
    render_rpc_error(:invalid_params, error.message)
  end

  def with_token
    if authenticate_mcp_token
      yield
    else
      render_rpc_error(:unauthorized, headers: {"WWW-Authenticate" => mcp_challenge})
    end
  end

  def refuse_insufficient_scope
    render_rpc_error(:insufficient_scope,
      headers: {"WWW-Authenticate" => mcp_challenge(error: "insufficient_scope", scope: "read write")})
  end

  # Legacy clients open with initialize and can show only this message, so it
  # names the revision this server speaks.
  def refuse_initialize
    render_rpc_error(:method_not_found,
      "This server speaks MCP #{Mcp::PROTOCOL_VERSION} only and has no initialize handshake. " \
      "Send each request with params._meta[\"#{PROTOCOL_VERSION_META}\"] = \"#{Mcp::PROTOCOL_VERSION}\".",
      data: {supported: SUPPORTED_VERSIONS})
  end

  def refused_meta?(params)
    meta = as_object(params["_meta"])
    version = meta[PROTOCOL_VERSION_META]

    if !version.is_a?(String) || !meta[CLIENT_CAPABILITIES_META].is_a?(Hash)
      render_rpc_error(:missing_meta, "params._meta must carry #{PROTOCOL_VERSION_META} and #{CLIENT_CAPABILITIES_META}")
    elsif SUPPORTED_VERSIONS.exclude?(version)
      render_rpc_error(:unsupported_protocol_version, data: {supported: SUPPORTED_VERSIONS, requested: version})
    end

    performed?
  end

  # The headers restate the body so an intermediary can route without parsing
  # it. A disagreement is refused rather than guessed at.
  def refused_headers?(method, params)
    expected = {"MCP-Protocol-Version" => params["_meta"][PROTOCOL_VERSION_META], "Mcp-Method" => method}
    expected["Mcp-Name"] = params["name"].to_s if method == "tools/call"

    header, _ = expected.find { |name, value| header_value(name, request.headers[name]) != value }
    return false unless header

    if request.headers[header].nil?
      render_rpc_error(:header_mismatch, "The #{header} header is required")
    else
      render_rpc_error(:header_mismatch, "The #{header} header does not match the request body")
    end
    true
  end

  # Mcp-Name carries a header-unsafe tool name as =?base64?…?=.
  def header_value(header, sent)
    match = BASE64_SENTINEL.match(sent) if sent && header == "Mcp-Name"
    return sent unless match

    match[1].unpack1("m0").force_encoding(Encoding::UTF_8)
  rescue ArgumentError
    nil
  end

  def parse_body
    JSON.parse(request.raw_post)
  rescue JSON::ParserError
    :unparseable
  end

  # A client sending a string or an array where the spec says object gets an
  # empty object, not a 500.
  def as_object(value)
    value.is_a?(Hash) ? value : {}
  end

  # Every result says it is complete and names the server: there is no
  # handshake left to have said it once.
  def render_result(result)
    render json: {
      jsonrpc: "2.0",
      id: @rpc_id,
      result: result.merge(resultType: "complete", _meta: {SERVER_INFO_META => server_info})
    }
  end

  def render_rpc_error(key, message = nil, data: nil, headers: {})
    error = ERRORS.fetch(key)
    headers.each { |name, value| response.set_header(name, value) }

    body = {code: error[:code], message: message || error[:message]}
    body[:data] = data if data
    render json: {jsonrpc: "2.0", id: @rpc_id, error: body}, status: error[:status]
  end

  def server_info
    {name: Rails.application.class.module_parent_name.underscore.dasherize, version: Mcp::SERVER_VERSION}
  end
end
